          '                linear-gradient(180deg, #2a2a2a 0%, #242424 100%);\n'
          '        }\n'
          '\n'
          '        .app {\n'
          '            display: grid;\n'
          '            grid-template-columns: 280px 1fr;\n'
          '            min-height: 100vh;\n'
          '        }\n'
          '\n'
          '        .sidebar {\n'
          '            background: var(--bg-sidebar);\n'
